with repaired as (
 update public.books b set isbn=x.selected_isbn,thumbnail_url=x.cover_url
 from cover_recovery_candidates x
 where b.id=x.id and b.user_id='__TARGET_USER_ID__'::uuid and b.title=x.title
 and b.series_title=x.series_title and b.volume_number is not distinct from x.volume_number
 and b.isbn is not distinct from x.isbn and nullif(b.thumbnail_url,'') is null
 and (x.isbn is not null or (b.book_format='comic' and coalesce(b.volume_kind,'main')='main'))
 and not exists(select 1 from public.books other where other.user_id=b.user_id and other.isbn=x.selected_isbn and other.id<>b.id)
 returning b.id
) select count(*) repaired from repaired;
select public.prepare_book_content_review(x.selected_isbn,
 encode(extensions.digest((coalesce(j.candidate,'{}'::jsonb)||jsonb_build_object('title',coalesce(nullif(j.candidate->>'title',''),x.selected_title),'publisher',coalesce(j.candidate->>'publisher',x.publisher,''),'cover_url',x.cover_url,'cover_hash',x.cover_hash,'source_url',x.source_url,'review_origin','registration'))::text,'sha256'),'hex'),
 coalesce(j.candidate,'{}'::jsonb)||jsonb_build_object('title',coalesce(nullif(j.candidate->>'title',''),x.selected_title),'publisher',coalesce(j.candidate->>'publisher',x.publisher,''),'cover_url',x.cover_url,'cover_hash',x.cover_hash,'source_url',x.source_url,'review_origin','registration'))
from cover_recovery_candidates x left join public.book_content_review_jobs j on j.isbn13=x.selected_isbn
where j.isbn13 is null or (j.adult_only is null and j.status in ('queued','retry','pending_review') and j.candidate->>'cover_hash' is null);
commit;

